import { and, eq, gt, inArray } from "drizzle-orm";
import { getDb } from "@/db";
import { lessonsDb, videoUploadSessions } from "@/db/schema";
import { getSessionUser, roleAllowed, sameOriginRequest, checkRateLimit } from "@/lib/auth";
import { isNativeAppRequest } from "@/lib/mobile-api";
import { jsonError } from "@/lib/api";
import { readBoundedJsonObject, RequestBodyTooLargeError } from "@/lib/request-body";
import { supervisorCourseAllowed } from "@/lib/supervisor-data-scope";
import { startVideoUpload, getVideoUpload, signVideoUploadPart, completeVideoUpload, abortVideoUpload, VideoUploadError } from "@/lib/video-upload-sessions";
import { UPLOAD_UUID, validateVideoManifest } from "@/lib/video-upload-policy";

async function handle(request: Request) {
  if (!sameOriginRequest(request) && !isNativeAppRequest(request)) return jsonError("تعذر التحقق من مصدر الطلب", 403);
  const user = await getSessionUser(request);
  if (!user || !roleAllowed(user, ["admin", "supervisor"])) return jsonError("غير مصرح برفع الفيديو", 403);
  if (!await checkRateLimit("video-multipart-control", `user:${user.id}`, 180, 60)) return jsonError("طلبات رفع كثيرة؛ أعد المحاولة بعد قليل.", 429);
  if (process.env.S3_MULTIPART_ENABLED !== "true") return jsonError("الرفع القابل للاستئناف لم يُفعّل لهذا التخزين بعد.", 503, "MULTIPART_NOT_ENABLED");
  try {
    const payload = request.method === "GET" ? { action: new URL(request.url).searchParams.get("action") === "list" ? "list" : "status", id: new URL(request.url).searchParams.get("id") } : await readBoundedJsonObject(request, 32 * 1024);
    if (payload.action === "list") {
      const sessions = await getDb().select({ id: videoUploadSessions.id, courseSlug: videoUploadSessions.courseSlug,
        lessonId: videoUploadSessions.lessonId, sizeBytes: videoUploadSessions.sizeBytes, status: videoUploadSessions.status,
        expiresAt: videoUploadSessions.expiresAt }).from(videoUploadSessions).where(and(eq(videoUploadSessions.userId, user.id),
          inArray(videoUploadSessions.status, ["uploading", "uploaded"]), gt(videoUploadSessions.expiresAt, new Date()))).limit(3);
      const allowed = [];
      for (const session of sessions) if (await supervisorCourseAllowed(user, session.courseSlug)) allowed.push(session);
      return Response.json({ ok: true, uploads: allowed }, { headers: { "cache-control": "no-store" } });
    }
    if (payload.action === "start") {
      const { clientRequestId, courseSlug, lessonId, contentType, sizeBytes, checksums } = payload;
      if (typeof clientRequestId !== "string" || !UPLOAD_UUID.test(clientRequestId) || typeof courseSlug !== "string" || !courseSlug || courseSlug.length > 120
          || typeof lessonId !== "string" || !lessonId || lessonId.length > 120 || typeof contentType !== "string" || typeof sizeBytes !== "number") return jsonError("بيانات الرفع غير صالحة", 400);
      validateVideoManifest(sizeBytes, checksums);
      if (!await supervisorCourseAllowed(user, courseSlug)) return jsonError("المادة خارج نطاق إشرافك", 403);
      const [lesson] = await getDb().select({ id: lessonsDb.id }).from(lessonsDb).where(and(eq(lessonsDb.id, lessonId), eq(lessonsDb.courseSlug, courseSlug))).limit(1);
      if (!lesson) return jsonError("أنشئ سجل الدرس قبل الرفع", 404);
      const upload = await startVideoUpload(user.id, { clientRequestId, courseSlug, lessonId, contentType, sizeBytes, checksums }, request.signal);
      return Response.json({ ok: true, upload }, { headers: { "cache-control": "no-store" } });
    }
    const id = payload.id;
    if (typeof id !== "string" || !UPLOAD_UUID.test(id)) return jsonError("جلسة الرفع غير موجودة", 404);
    // Check current ownership and current scope before any S3 request, even for status or cancellation.
    const [session] = await getDb().select({ courseSlug: videoUploadSessions.courseSlug }).from(videoUploadSessions)
      .where(and(eq(videoUploadSessions.id, id), eq(videoUploadSessions.userId, user.id))).limit(1);
    if (!session) return jsonError("جلسة الرفع غير موجودة", 404);
    if (!await supervisorCourseAllowed(user, session.courseSlug)) return jsonError("المادة خارج نطاق إشرافك", 403);
    if (payload.action === "sign") {
      if (typeof payload.partNumber !== "number" || !Number.isSafeInteger(payload.partNumber)) return jsonError("جزء رفع غير صالح", 400);
      return Response.json({ ok: true, part: await signVideoUploadPart(user.id, id, payload.partNumber) }, { headers: { "cache-control": "no-store" } });
    }
    if (payload.action === "abort") { await abortVideoUpload(user.id, id); return Response.json({ ok: true }, { headers: { "cache-control": "no-store" } }); }
    const upload = payload.action === "complete" ? await completeVideoUpload(user.id, id, request.signal)
      : payload.action === "status" ? await getVideoUpload(user.id, id, request.signal) : null;
    if (!upload) return jsonError("إجراء رفع غير معروف", 400);
    return Response.json({ ok: true, upload }, { headers: { "cache-control": "no-store" } });
  } catch (error) {
    if (error instanceof RequestBodyTooLargeError) return jsonError("طلب الرفع أكبر من المسموح", 413);
    if (error instanceof TypeError && error.message === "Invalid JSON object") return jsonError("بيانات الرفع غير صالحة", 400);
    if (error instanceof VideoUploadError) return jsonError(error.message, error.status);
    if (error instanceof RangeError || error instanceof SyntaxError || error instanceof Error && /^Invalid video/.test(error.message)) return jsonError("بيانات أو بصمة الرفع غير صالحة", 400);
    return jsonError("تعذر إكمال عملية التخزين. يمكنك الاستئناف دون إعادة الأجزاء المكتملة.", 503);
  }
}
export const GET = handle;
export const POST = handle;
